/* Trooper hit handler: takes damage, then knocks back away from the attacker by hit strength (dying on lethal hits).
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l03/gameplay/entities/002c9eb8.c, FUN_L03_002ca808. */
void handle_mine_layer_damage(struct Moby *m) {
    TrooperVars_CBBD0 *v = (TrooperVars_CBBD0 *)m->pvars;
    TrooperHit_CBBD0 *h;
    Vec4 at;
    s32 hit;
    f32 dmg;
    f32 ang;
    s32 r;

    dmg = 0.0f;
    h = MobyGetHitMessage_r(m, 0x330000, 0);
    r = ComputeHitResponse(m, h, &v->health, 0, &hit, &dmg, 0, 4);
    if (hit != 1 && m->state != 5) {
        if (h->source != 0) {
            if (h->source != g_hero_r.items[0].moby)
                ang = fast_atan2(m->pos.x - h->source->pos.x, m->pos.y - h->source->pos.y);
            else
                ang = fast_atan2(m->pos.x - g_hero_r.motion.pos.f[0], m->pos.y - g_hero_r.motion.pos.f[1]);
        } else {
            ang = fast_atan2(m->pos.x - g_hero_r.motion.pos.f[0], m->pos.y - g_hero_r.motion.pos.f[1]);
        }
        v->health -= dmg;
        if (v->health <= 0.0f)
            r = 1;
        switch (r) {
        case 3:
        case 6:
            v->kb_speed = D_L03_0016197C_CBBD0 * g_frame_time_sq;
            trooper_set_knockback(v->knockback, D_L03_00161980_CBBD0, D_L03_00161984_CBBD0);
            v->kb_landed = 0;
            v->kb_frames = 9;
            *(u128_CBBD0 *)&at = *(u128_CBBD0 *)&h->pos;
            HeadingFromVector(&at, &ang, &v->kb_lift, &v->kb_gravity);
            InitKnockback_r(fast_atan2(m->pos.x - g_hero_r.motion.pos.f[0], m->pos.y - g_hero_r.motion.pos.f[1]),
                                    m, v->knockback, 3, 1, 0);
            v->kb_min = 5.0f;
            v->kb_max = 10.0f;
            m->state = 4;
            break;
        case 4:
        case 5:
            v->kb_speed = D_L03_0016197C_CBBD0 * g_frame_time_sq;
            trooper_set_knockback(v->knockback, D_L03_00161980_CBBD0, D_L03_00161984_CBBD0);
            v->kb_landed = 0;
            v->kb_frames = 9;
            *(u128_CBBD0 *)&at = *(u128_CBBD0 *)&h->pos;
            HeadingFromVector(&at, &ang, &v->kb_lift, &v->kb_gravity);
            InitKnockback_r(fast_atan2(m->pos.x - g_hero_r.motion.pos.f[0], m->pos.y - g_hero_r.motion.pos.f[1]),
                                    m, v->knockback, 4, 1, 0);
            v->kb_min = 7.5f;
            v->kb_max = 15.0f;
            m->state = 4;
            break;
        case 1:
            v->kb_speed = D_L03_00161978_CBBD0 * g_frame_time_sq;
            trooper_set_knockback(v->knockback, D_L03_00161988_CBBD0, D_L03_0016198C_CBBD0);
            v->kb_landed = 0;
            v->kb_frames = 9;
            *(u128_CBBD0 *)&at = *(u128_CBBD0 *)&h->pos;
            HeadingFromVector(&at, &ang, &v->kb_lift, &v->kb_gravity);
            InitKnockback_r(fast_atan2(m->pos.x - g_hero_r.motion.pos.f[0], m->pos.y - g_hero_r.motion.pos.f[1]),
                                    m, v->knockback, 5, 1, 0);
            v->kb_min = 8.0f;
            v->kb_max = 15.0f;
            m->flags &= 0xEFFF;
            *((u8 *)v + 0x67) = 0xFA;
            m->state = 5;
            break;
        }
        RerollEffectCounter(m, v->anim);
    }
    m->hit_slot = 0xFF;
    StepColorFade(m, v->anim);
}
